import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"50、【鼎】 巽下离上","description":"横渠易说 - 50、【鼎】 巽下离上","frontmatter":{"title":"50、【鼎】 巽下离上","description":"横渠易说 - 50、【鼎】 巽下离上"},"headers":[],"relativePath":"zh/classics/hengqu/052.md","filePath":"zh/classics/hengqu/052.md"}'),l={name:"zh/classics/hengqu/052.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_50、【鼎】-巽下离上" tabindex="-1">50、【鼎】 巽下离上 <a class="header-anchor" href="#_50、【鼎】-巽下离上" aria-label="Permalink to “50、【鼎】 巽下离上”">​</a></h1><h3 id="彖曰-鼎-象也-以木巽火-亨饪也。圣人亨以享上帝-而大亨以养圣贤。巽而耳目聪明-柔进而上行-得中而应乎刚-是以元亨。" tabindex="-1">彖曰：鼎，象也，以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。 <a class="header-anchor" href="#彖曰-鼎-象也-以木巽火-亨饪也。圣人亨以享上帝-而大亨以养圣贤。巽而耳目聪明-柔进而上行-得中而应乎刚-是以元亨。" aria-label="Permalink to “彖曰：鼎，象也，以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。”">​</a></h3><h3 id="象曰-木上有火-鼎-君子以正位凝命。" tabindex="-1">象曰：木上有火，鼎，君子以正位凝命。 <a class="header-anchor" href="#象曰-木上有火-鼎-君子以正位凝命。" aria-label="Permalink to “象曰：木上有火，鼎，君子以正位凝命。”">​</a></h3><p>正始而取新，莫先于正位而定命也。</p><h3 id="初六-鼎颠趾-利出否。得妾以其子-无咎。-象曰-鼎颠趾-未悖也。-利出否-以从贵也。" tabindex="-1">初六，鼎颠趾，利出否。得妾以其子，无咎。 象曰：“鼎颠趾”，未悖也。“利出否”，以从贵也。 <a class="header-anchor" href="#初六-鼎颠趾-利出否。得妾以其子-无咎。-象曰-鼎颠趾-未悖也。-利出否-以从贵也。" aria-label="Permalink to “初六，鼎颠趾，利出否。得妾以其子，无咎。 象曰：“鼎颠趾”，未悖也。“利出否”，以从贵也。”">​</a></h3><p>柔牵于上，必有义乃可。鼎颠趾必出否，妾从子贵，必以有子乃不悖于义也。</p><h3 id="九二-鼎有实-我仇有疾-不我能即-吉。-象曰-鼎有实-慎所之也。-我仇有疾-终无尤也。" tabindex="-1">九二，鼎有实，我仇有疾，不我能即，吉。 象曰：“鼎有实”，慎所之也。“我仇有疾”，终无尤也。 <a class="header-anchor" href="#九二-鼎有实-我仇有疾-不我能即-吉。-象曰-鼎有实-慎所之也。-我仇有疾-终无尤也。" aria-label="Permalink to “九二，鼎有实，我仇有疾，不我能即，吉。 象曰：“鼎有实”，慎所之也。“我仇有疾”，终无尤也。”">​</a></h3><p>以阳居中，故有实，实而与物竞，则所丧多矣，故所之不可不慎也。我仇谓三也，三为革为塞，固己路而为患者也，使其有疾而不能加我，则美实可保而吉可致也。然四亦恶三，三常惧焉，是有疾而无尤也。</p><h3 id="九三-鼎耳革-其行塞-雉膏不食-方雨亏悔-终吉。-象曰-鼎耳革-失其义也。" tabindex="-1">九三，鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。 象曰：“鼎耳革”，失其义也。 <a class="header-anchor" href="#九三-鼎耳革-其行塞-雉膏不食-方雨亏悔-终吉。-象曰-鼎耳革-失其义也。" aria-label="Permalink to “九三，鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。 象曰：“鼎耳革”，失其义也。”">​</a></h3><p>耳革行塞，处二阳之间，上下俱实也。上下革塞，则虽有美实而不见取。若二使应五，四使应初，则其悔可亏，故曰“方雨亏悔”，能终不固塞其路则吉可召也，革塞之则失其义矣。以阳居阳，承乘皆刚，悔也，有九四之革，其行不得上通，此鼎耳之失义也。</p><h3 id="九四-鼎折足-覆公餗-其形渥-凶。-象曰-覆公餗-信如何也" tabindex="-1">九四，鼎折足，覆公餗，其形渥，凶。 象曰：“覆公餗”，信如何也! <a class="header-anchor" href="#九四-鼎折足-覆公餗-其形渥-凶。-象曰-覆公餗-信如何也" aria-label="Permalink to “九四，鼎折足，覆公餗，其形渥，凶。 象曰：“覆公餗”，信如何也!”">​</a></h3><h3 id="六五-鼎黄耳金铉-利贞。-象曰-鼎黄耳-中以为实也。" tabindex="-1">六五，鼎黄耳金铉，利贞。 象曰：“鼎黄耳”，中以为实也。 <a class="header-anchor" href="#六五-鼎黄耳金铉-利贞。-象曰-鼎黄耳-中以为实也。" aria-label="Permalink to “六五，鼎黄耳金铉，利贞。 象曰：“鼎黄耳”，中以为实也。”">​</a></h3><p>居中故其耳黄，体柔故其铉金，柔故利于贞。一作利于劲正。</p><h3 id="上九-鼎玉铉-大吉无不利。-象曰-玉铉在上-刚柔节也。" tabindex="-1">上九，鼎玉铉，大吉无不利。 象曰：玉铉在上，刚柔节也。 <a class="header-anchor" href="#上九-鼎玉铉-大吉无不利。-象曰-玉铉在上-刚柔节也。" aria-label="Permalink to “上九，鼎玉铉，大吉无不利。 象曰：玉铉在上，刚柔节也。”">​</a></h3><p>以刚居上，能贞洁如玉以成鼎道，不牵阴柔以固其节，则吉无不利。鼎，象也，足阴腹阳，耳虚铉刚，故曰“刚柔节”也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
